fields.InputDefinition:
{
  "goal": "Open the 'Members' entity via the LEFT sidebar 'Search entities...' box (type 'Members', click the exact match), click a member row, then click 'Open Full Record' to load the full form. This shared setup is done ONCE. Then exercise these form controls IN ORDER, and as you finish each set \"checkpointReached\" to the exact checkpoint name shown: (1) section-search — in the toolbar 'Search sections...' input, type a term matching a section name and confirm the sections narrow to matches, then type gibberish (e.g. 'zzzqqq') and confirm a 'No sections found' empty state with a 'Clear search' action, then clear the search; (2) section-nav — the form lists its sections in a LEFT navigation rail (Details, Forum Posts, Email Sends, ...); click a section other than the current one (e.g. 'Forum Posts') and confirm the form body switches to that section's content and the rail highlights it; (3) width-toggle — click the width-toggle icon button (tooltip 'Expand to full width' / 'Center content') and confirm the form content layout width visibly changes; (4) section-manager — click the 'Manage section order' icon button (bars-staggered) and confirm the 'Manage Sections' drawer opens listing sections with up/down arrows and a 'Reset to Default Order' option, then close it; (5) section-rail-toggle — click the rail's 'Hide sections' button (double chevron «) and confirm the left rail collapses to a narrow vertical tab labeled with the current section, then click that tab ('Show sections') and confirm the full rail returns. Keep going until every control has been exercised. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 65,
  "checkpoints": [
    {
      "name": "section-search",
      "instruction": "section search-filter narrows and shows no-match empty state",
      "visualCriteria": [
        "Typing a matching term in the form's 'Search sections...' box narrows the visible sections to matches, and typing a non-matching term shows a 'No sections found' empty state with a Clear search option"
      ]
    },
    {
      "name": "section-nav",
      "instruction": "left section rail switches the form body",
      "visualCriteria": [
        "Clicking a different section in the form's left navigation rail (e.g. Forum Posts) switches the form body to that section's content and highlights it in the rail"
      ]
    },
    {
      "name": "width-toggle",
      "instruction": "form width toggle changes content width",
      "visualCriteria": [
        "Clicking the width-toggle button (Expand to full width / Center content) visibly changes the form content layout width — the panels widen to full-width or re-center"
      ]
    },
    {
      "name": "section-manager",
      "instruction": "Manage Sections drawer opens with reorder controls",
      "visualCriteria": [
        "Clicking the 'Manage section order' toolbar button opens a 'Manage Sections' drawer listing the form's sections with up/down move buttons and a 'Reset to Default Order' option"
      ]
    },
    {
      "name": "section-rail-toggle",
      "instruction": "hide then show the section rail",
      "visualCriteria": [
        "Clicking 'Hide sections' collapses the left section rail to a narrow vertical tab, and clicking that tab ('Show sections') restores the full rail"
      ]
    }
  ]
}
